  'mobility-early':{name:'Glider-Scout',weapon:'Sword of the Lord + Noble Man\'s Bow',armor:'Grey Wolf Leather',cores:'Speed Lv.2 · Wind Slash',skills:'Evasive Roll · Flight (Crow\'s Wing) · Dodge',tip:'Noble Man\'s Bow + Flight für Aerial-Recon. Evasive Roll per Watch & Learn im Kailok-Kampf (Ende Kap. 2; bei Verpassen Rematch am Memory Fragment) oder für 1 AA.'},
  'mobility-mid':{name:'Aerial Hawk',weapon:'Tauria Curved Sword',armor:'Blackwing Leather (post-Draven)',cores:'Speed Lv.2 · Crow\'s Pursuit · Wind Slash',skills:'Aerial Roll · Aerial Force Palm · Dodge · Glide',tip:'Blackwing Set + Aerial Roll = unschlagbar in offenem Terrain. Crow\'s Pursuit-Damage scaled mit Movement.'},
  'mobility-late':{name:'Wind-Walker',weapon:'Tauria Curved Sword (Refined 5)',armor:'Dark Marksman + Blackwing Mix',cores:'Wind Slash · Crow\'s Pursuit · Swift II · Haste I',skills:'Aerial Roll · Aerial Force Palm · Storm Veil · Diving Force Palm',tip:'Storm Veil ab Kap. 8 via Riddle Square Chain. Diving Force Palm aus dem Precipice-of-Truth-Puzzle (Abyss).'},
  'mobility-end':{name:'Blackstar-Hunter',weapon:'Tauria Curved Sword Refine 5',armor:'Blackwing + Combat God Mix',cores:'Wind Slash · Crow\'s Pursuit · Greater Swift · Haste I · Storm Fang',skills:'Aerial Force Palm · Falling Palm · Diving Force Palm · Storm Veil',tip:'Blackstar-Mount für Umbra. Falling Palm aus Drache abspringen = 1-Shot.'},
  'caster-early':{name:'Spirit-Channeler',weapon:'Hwando + Hollow Visage',armor:'Light Battlefield Cloak',cores:'Insight I · Destruction I',skills:'Force Palm Lv 2 · Focus · Nature\'s Grasp',tip:'Hollow Visage aus Dawn Cave hat Insight built-in. Force Palm Lv 2 via Force Palm Pulse-Quest.'},
  'caster-mid':{name:'Element-Adept',weapon:'Frozen Anguish (2H)',armor:'Frostcursed Set',cores:'Stamina Transference · Destruction I · Insight I',skills:'Flame Strike · Frost Mantle · Lightning Surge · Imbue Element Lv 2 · Focus Lv 2',tip:'Frostcursed Set gibt Eis-Resistenz (keine Immunität); Frost Mantle ist eine Frost-Barriere (10 Spirit) — ein Kombo-Effekt ist nicht belegt. Frost-Element: Rätsel im Spire of Ringing Truth (Priscus), danach Ether Rest, Frostbitten Paradise und Path of Trials.'},
  'caster-late':{name:'Storm-Sage',weapon:'Crow Whisperer (Hexe Marie Drop)',armor:'Blackwing Leather + Combat God Gloves',cores:'Ator\'s Orb · Lightning God\'s Affliction · Spirit\'s Judgment',skills:'Storm Veil · Imbue Element Lv 4 · Focus Lv 2 · Force Palm Expertise',tip:'Crow Whisperer + alle 4 Elemente. Storm Veil + Focused Repulsion = Boss-Lockdown.'},
  'caster-end':{name:'Falling-Palm-God',weapon:'Twisted Verdict',armor:'Combat God Gloves + Plate of Shadows',cores:'Abyssal Rays · Ator\'s Orb · Lightning God\'s Affliction · Spirit\'s Judgment',skills:'Falling Palm · Force Palm Expertise · Nature\'s Echo · Imbue Element Lv 4',tip:'Falling Palm aus terminaler Fallgeschwindigkeit + Imbue Element = brutaler Single-Hit. Mystical Storage als Kuku-Toolkit.'},
  'ranged-early':{name:'Marksman Start',weapon:'Noble Man\'s Bow',armor:'Light Battlefield Set',cores:'Crit Rate Lv.2',skills:'Marksmanship Lv 3 · Charged Shot · Multishot (Watch&Learn Fort Warspike)',tip:'Fort Warspike Commander droppt sowohl Multishot ALS AUCH Explosive Evasive Shot — Pflicht!'},
  'ranged-mid':{name:'Infinite-Arrow',weapon:'Warspike Bow',armor:'Dark Marksman Boots + Blackwing',cores:'Infinite Arrows III · Crow\'s Pursuit · Crit Rate Lv.2',skills:'Marksmanship Lv 5 · Explosive Evasive Shot · Multishot · Focus',tip:'Crit-Scaling-Build via Warspike. Infinite Arrows = nie nachladen.'},
  'ranged-late':{name:'Sniper-Storm',weapon:'Divine Echoes Bow + Caliburn\'s Mercy Pistol (Quick Swap)',armor:'Dark Marksman Set',cores:'Infinite Arrows III · Crit Damage · Wind Slash',skills:'Multishot · Aerial Roll · Storm Veil · Focus Lv 2',tip:'Quick Swap zwischen Bow + Pistole für Burst. Storm Veil hidet vor Adds.'},
  'ranged-end':{name:'Aeserion-Hunter',weapon:'Aeserion Bow + Divine Echoes Bow',armor:'Combat God Gloves + Dark Marksman',cores:'Greater Infinite Arrows · Greater Destruction · Wind Slash · Storm Fang',skills:'Multishot · Aerial Roll · Falling Palm (Air-Shot) · Imbue Element Lv 4',tip:'Aeserion Bow ab Kap. 12. Imbued Arrows für Element-Schwächen.'},
  'unarmed-early':{name:'Fist-Bandit',weapon:'(unarmed)',armor:'Light Battlefield Cloak',cores:'(in Armor)',skills:'Unarmed Combat Lv 3 · Pump Kick (Matthias!) · Dropkick (Watch&Learn Axt-Banditen)',tip:'Pump Kick beim Matthias-Boss (Kap. 2, For Honor): per Watch & Learn im Duell abschauen. Sofort einbinden.'},
  'unarmed-mid':{name:'Wrestler',weapon:'Mining Knuckledrill (auch Pickaxe)',armor:'Combat God\'s Plate Gloves (BIS)',cores:'Move Speed Lv.4 · Lightning Affinity',skills:'Body Slam · Clothesline · Vault · Meteor Kick · Grappling Lv 5',tip:'Mining Knuckledrill + Pickaxe-Funktion. Combat God\'s Plate Gloves früh sichern.'},
  'unarmed-late':{name:'Brawler-King',weapon:'Combat God\'s Plate Gloves + Savage Sawblade Quick Swap',armor:'Hungering Fang Leather + Combat God Gloves',cores:'Relentless · Lightning Affinity · Bleed (Savage)',skills:'Meteor Kick · Clothesline · Pump Kick · Body Slam · Blinding Flash Finisher',tip:'Blinding Flash Finisher seit 1.07 auch unbewaffnet ausführbar.'},
  'unarmed-end':{name:'Pure-Fist',weapon:'Combat God\'s Plate Gloves',armor:'Combat God Gloves + Plate of Shadows',cores:'Abyssal Rays · Greater Steelbane · Lightning Affinity · Malicebane',skills:'Meteor Kick · Falling Palm · Blinding Flash Finisher · Force Palm Expertise · Nature\'s Echo',tip:'Falling Palm auch ohne Waffe brutal. Nature\'s Echo verdoppelt jeden Faustschlag.'}
